# typed: strict
# frozen_string_literal: true

return unless defined?(ActiveRecord::Base)

require 'tapioca/dsl/compilers/active_record_relations'

module Tapioca
  module Dsl
    module Compilers
      # Adds `virtual_joins` to the relations generated by the ActiveRecordRelations compiler,
      # for models extended by ActiveRecord::VirtualJoins.
      # (Relations delegate it to their model, so it isn't otherwise known to be a relation method.)
      # Compilers decorate a constant in order of their names, so this runs after ActiveRecordRelations.
      #
      #: [ConstantType = singleton(::ActiveRecord::Base)]
      class ActiveRecordVirtualJoins < Compiler
        include Helpers::ActiveRecordConstantsHelper

        # @override
        #: -> void
        def decorate
          return unless compiler_enabled?('ActiveRecordRelations')

          root.create_path(constant) do |model|
            model.create_module(RelationMethodsModuleName) do |mod|
              create_virtual_joins_method(mod, RelationClassName)
            end

            model.create_module(AssociationRelationMethodsModuleName) do |mod|
              create_virtual_joins_method(mod, AssociationRelationClassName)
            end
          end
        end

        class << self
          # @override
          #: -> Enumerable[Module[top]]
          def gather_constants
            ActiveRecordRelations.gather_constants.grep(::ActiveRecord::VirtualJoins)
          end
        end

      private

        #: (RBI::Scope scope, String return_type) -> void
        def create_virtual_joins_method(scope, return_type)
          scope.create_method(
            'virtual_joins',
            parameters: [
              create_param('join_column_name', type: 'T.any(Symbol, String)'),
              create_param('join_values', type: 'T::Enumerable[T::Hash[T.any(Symbol, String), T.untyped]]'),
              create_kw_opt_param('join_table_name', type: 'T.any(Symbol, String)', default: default_join_table_name),
              create_kw_rest_param('join_value_types', type: 'T.any(Symbol, String)'),
            ],
            return_type:
          )
        end

        # The default depends on the join column, so it's given as the expression which computes it.
        #
        #: -> String
        def default_join_table_name
          '"#{table_name}_#{join_column_name}_json"' # rubocop:disable Lint/InterpolationCheck
        end
      end
    end
  end
end
